        require(msg.sender != c.owner());
        require(c.owner() != address(this));
        require(address(this).balance >= _value);
        require(_value > address(c).balance);
        require(_target == address(this));
        bool ok; c.sendMoney(_target, _value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }
