// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _testNonOwnerCannotSendMoney(address _target, uint256 _value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(msg.sender != c.owner());
        vm.assume(c.owner() != address(this));
        vm.assume(address(this).balance >= _value);
        vm.assume(_value > address(c).balance);
        _target = address(this);
        bool ok;
        try c.sendMoney(_target, _value) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }

    function testFuzz_testNonOwnerCannotSendMoney(address _target, uint256 _value) public {
        _testNonOwnerCannotSendMoney(_target, _value);
    }

    receive() external payable {}
}
